@preconcurrency import SwiftNumber
@preconcurrency import Eth
import Foundation

public enum UnloopShort {
    public struct MarketParams: Equatable, Sendable {
        public static let schema: ABI.Schema = ABI.Schema.tuple([.address, .address, .address, .address, .uint256])

        public let loanToken: EthAddress
        public let collateralToken: EthAddress
        public let oracle: EthAddress
        public let irm: EthAddress
        public let lltv: Number

        public init(loanToken: EthAddress, collateralToken: EthAddress, oracle: EthAddress, irm: EthAddress, lltv: Number) {
          self.loanToken = loanToken
         self.collateralToken = collateralToken
         self.oracle = oracle
         self.irm = irm
         self.lltv = lltv
        }

        public var encoded: Hex {
            asValue.encoded
        }

        public var asValue: ABI.Value {
            .tuple5(.address(loanToken),
             .address(collateralToken),
             .address(oracle),
             .address(irm),
             .uint256(lltv))
        }

        public static func decode(hex: Hex) throws -> MarketParams {
            if let value = try? schema.decode(hex) {
                return try decodeValue(value)
            }
  // both versions are valid encodings of tuples with dynamic fields ( bytes or string ), so try both decodings
  if case let .tuple1(wrappedValue) = try? ABI.Schema.tuple([schema]).decode(hex) {
      return try decodeValue(wrappedValue)
  }
  // retry original to throw the error
  return try decodeValue(schema.decode(hex))


        }

        public static func decodeValue(_ value: ABI.Value) throws -> MarketParams {
            switch value {
            case let .tuple5(.address(loanToken),
             .address(collateralToken),
             .address(oracle),
             .address(irm),
             .uint256(lltv)):
                return MarketParams(loanToken: loanToken, collateralToken: collateralToken, oracle: oracle, irm: irm, lltv: lltv)
            default:
                throw ABI.DecodeError.mismatchedType(value.schema, schema)
            }
        }
    }
    public struct UnloopInfo: Equatable, Sendable {
        public static let schema: ABI.Schema = ABI.Schema.tuple([.address, .address, .uint24, .uint256, .uint256, .uint256, .uint256, .address])

        public let exposureToken: EthAddress
        public let backingToken: EthAddress
        public let poolFee: UInt
        public let exposureAmount: Number
        public let backingAmountToExit: Number
        public let maxSwapBackingAmount: Number
        public let feeAmount: Number
        public let feeRecipient: EthAddress

        public init(exposureToken: EthAddress, backingToken: EthAddress, poolFee: UInt, exposureAmount: Number, backingAmountToExit: Number, maxSwapBackingAmount: Number, feeAmount: Number, feeRecipient: EthAddress) {
          self.exposureToken = exposureToken
         self.backingToken = backingToken
         self.poolFee = poolFee
         self.exposureAmount = exposureAmount
         self.backingAmountToExit = backingAmountToExit
         self.maxSwapBackingAmount = maxSwapBackingAmount
         self.feeAmount = feeAmount
         self.feeRecipient = feeRecipient
        }

        public var encoded: Hex {
            asValue.encoded
        }

        public var asValue: ABI.Value {
            .tuple8(.address(exposureToken),
             .address(backingToken),
             .uint24(poolFee),
             .uint256(exposureAmount),
             .uint256(backingAmountToExit),
             .uint256(maxSwapBackingAmount),
             .uint256(feeAmount),
             .address(feeRecipient))
        }

        public static func decode(hex: Hex) throws -> UnloopInfo {
            if let value = try? schema.decode(hex) {
                return try decodeValue(value)
            }
  // both versions are valid encodings of tuples with dynamic fields ( bytes or string ), so try both decodings
  if case let .tuple1(wrappedValue) = try? ABI.Schema.tuple([schema]).decode(hex) {
      return try decodeValue(wrappedValue)
  }
  // retry original to throw the error
  return try decodeValue(schema.decode(hex))


        }

        public static func decodeValue(_ value: ABI.Value) throws -> UnloopInfo {
            switch value {
            case let .tuple8(.address(exposureToken),
             .address(backingToken),
             .uint24(poolFee),
             .uint256(exposureAmount),
             .uint256(backingAmountToExit),
             .uint256(maxSwapBackingAmount),
             .uint256(feeAmount),
             .address(feeRecipient)):
                return UnloopInfo(exposureToken: exposureToken, backingToken: backingToken, poolFee: poolFee, exposureAmount: exposureAmount, backingAmountToExit: backingAmountToExit, maxSwapBackingAmount: maxSwapBackingAmount, feeAmount: feeAmount, feeRecipient: feeRecipient)
            default:
                throw ABI.DecodeError.mismatchedType(value.schema, schema)
            }
        }
    }
    public static let creationCode: Hex = ""
    public static let runtimeCode: Hex = ""

    public static let ExitBackingAmountTooHighError = ABI.Function(
            name: "ExitBackingAmountTooHigh",
            inputs: [.address, .uint256, .uint256]
    )

    public static let ExposureAmountTooHighError = ABI.Function(
            name: "ExposureAmountTooHigh",
            inputs: [.address, .uint256, .uint256]
    )

    public static let FeeTooHighError = ABI.Function(
            name: "FeeTooHigh",
            inputs: [.uint256, .uint256]
    )

    public static let InvalidCallerError = ABI.Function(
            name: "InvalidCaller",
            inputs: []
    )

    public static let InvalidFeeRecipientError = ABI.Function(
            name: "InvalidFeeRecipient",
            inputs: []
    )

    public static let InvalidMarketParamsError = ABI.Function(
            name: "InvalidMarketParams",
            inputs: []
    )

    public static let MissingSlippageProtectionError = ABI.Function(
            name: "MissingSlippageProtection",
            inputs: []
    )

    public static let NonZeroExitOnMaxUnloopError = ABI.Function(
            name: "NonZeroExitOnMaxUnloop",
            inputs: [.address, .uint256]
    )

    public static let ReentrantCallError = ABI.Function(
            name: "ReentrantCall",
            inputs: []
    )

    public static let SwapTooExpensiveError = ABI.Function(
            name: "SwapTooExpensive",
            inputs: [.address, .uint256, .uint256]
    )

    public static let SwapUnderfilledError = ABI.Function(
            name: "SwapUnderfilled",
