    public static let addBackingTokenFn = ABI.Function(
            name: "addBackingToken",
            inputs: [.address, .tuple([.address, .address, .address, .address, .uint256]), .uint256, .bool],
            outputs: []
    )

    public static func addBackingToken(morpho: EthAddress, morphoMarketParams: MarketParams, amount: Number, cappedMax: Bool, withFunctions ffis: EVM.FFIMap = [:]) throws -> Result<(), RevertReason> {
            do {
                let query = try addBackingTokenFn.encoded(with: [.address(morpho), morphoMarketParams.asValue, .uint256(amount), .bool(cappedMax)])
                let result = try EVM.runQuery(bytecode: runtimeCode, query: query, withErrors: errors, withFunctions: ffis)
                let decoded = try addBackingTokenFn.decode(output: result)

                switch decoded {
                case  .tuple0:
                    return .success(())
                default:
                    throw ABI.DecodeError.mismatchedType(decoded.schema, addBackingTokenFn.outputTuple)
                }
            } catch let EVM.QueryError.error(e, v) {
                return .failure(rewrapError(e, value: v))
            }
    }


    public static func addBackingTokenDecode(input: Hex) throws -> (EthAddress, MarketParams, Number, Bool) {
        let decodedInput = try addBackingTokenFn.decodeInput(input: input)
        switch decodedInput {
        case let .tuple4(.address(morpho), .tuple5(.address(loanToken),
 .address(collateralToken),
 .address(oracle),
 .address(irm),
 .uint256(lltv)), .uint256(amount), .bool(cappedMax)):
            return try (morpho, MarketParams(loanToken: loanToken, collateralToken: collateralToken, oracle: oracle, irm: irm, lltv: lltv), amount, cappedMax)
        default:
            throw ABI.DecodeError.mismatchedType(decodedInput.schema, addBackingTokenFn.inputTuple)
        }
    }

