    public static func unloop(morpho: EthAddress, morphoMarketParams: MarketParams, unloopInfo: UnloopInfo, withFunctions ffis: EVM.FFIMap = [:]) throws -> Result<(), RevertReason> {
            do {
                let query = try unloopFn.encoded(with: [.address(morpho), morphoMarketParams.asValue, unloopInfo.asValue])
                let result = try EVM.runQuery(bytecode: runtimeCode, query: query, withErrors: errors, withFunctions: ffis)
                let decoded = try unloopFn.decode(output: result)

                switch decoded {
                case  .tuple0:
