            } catch let EVM.QueryError.error(e, v) {
                return .failure(rewrapError(e, value: v))
            }
    }


    public static func unloopDecode(input: Hex) throws -> (EthAddress, MarketParams, UnloopInfo) {
        let decodedInput = try unloopFn.decodeInput(input: input)
        switch decodedInput {
        case let .tuple3(.address(morpho), .tuple5(.address(loanToken),
 .address(collateralToken),
 .address(oracle),
 .address(irm),
 .uint256(lltv)), .tuple8(.address(exposureToken),
 .address(backingToken),
 .uint24(poolFee),
 .uint256(exposureAmount),
 .uint256(backingAmountToExit),
 .uint256(maxSwapBackingAmount),
 .uint256(feeAmount),
 .address(feeRecipient))):
